import{_ as a,o,c as i,ak as s}from"./chunks/framework.Dpc0wyhY.js";const m=JSON.parse('{"title":"Messages","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/messaging/messages.md","filePath":"generated/grindr-api/messaging/messages.md"}'),d={name:"grindr-api/messaging/messages.md"};function l(t,e,n,r,c,g){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to “Messages”">​</a></h1><h2 id="get-messages-in-a-conversation" tabindex="-1">Get messages in a conversation <a class="header-anchor" href="#get-messages-in-a-conversation" aria-label="Permalink to “Get messages in a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Invoking this endpoint does not <a href="/grindr-api/messaging/conversations#mark-messages-as-read">mark messages as read</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v5/chat/conversation/{conversationId}/message</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>pageKey</code> — string, optional, return messages with IDs before specified value, optional</li><li><code>profile</code> — boolean (<code>profile=true</code> | <code>profile=</code> + any other value), optional</li></ul><p>Response:</p><ul><li><code>lastReadTimestamp</code> — unix timestamp of recipient&#39;s side in milliseconds or <code>null</code>; is not affected by yours calls to <a href="/grindr-api/messaging/conversations#mark-messages-as-read">mark messages as read</a></li><li><code>messages</code> — array of <a href="/grindr-api/messaging/messages#message">Message</a></li><li><code>metadata</code> — object <ul><li><code>translate</code> — boolean</li><li><code>hasSharedAlbums</code> — boolean</li><li><code>isInAList</code> — boolean</li></ul></li><li><code>profile</code> — object if <code>profile</code> query parameter is set to <code>true</code> or <code>null</code></li></ul><h2 id="get-a-single-message-in-a-conversation" tabindex="-1">Get a single message in a conversation <a class="header-anchor" href="#get-a-single-message-in-a-conversation" aria-label="Permalink to “Get a single message in a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/chat/conversation/{conversationId}/message/{messageId}</span></span></code></pre></div><p>Response:</p><ul><li><code>message</code> — <a href="/grindr-api/messaging/messages#message">Message</a></li></ul><h2 id="send-a-message-to-a-conversation" tabindex="-1">Send a message to a conversation <a class="header-anchor" href="#send-a-message-to-a-conversation" aria-label="Permalink to “Send a message to a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Please don&#39;t use this for spam. Be civil.</p><p>When <code>replyToMessageId</code> is used in HTTP API appears to cause 400 Bad Request error.</p><p>See also: <a href="/grindr-api/websocket/commands#send-a-message-to-a-conversation-via-ws">Send a message to a conversation via ws</a></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/message/send</span></span></code></pre></div><p>Body:</p><ul><li><code>type</code> — <a href="/grindr-api/messaging/messages#message-type">Message type</a></li><li><code>target</code> — <a href="/grindr-api/messaging/messages#messagetarget">MessageTarget</a></li><li><code>body</code> — object with <a href="/grindr-api/messaging/messages#message-contents">Message contents</a> or <code>null</code></li></ul><p>Response:</p><p>HTTP status 201. <a href="/grindr-api/messaging/messages#message">Message</a> object.</p><h2 id="unsend-a-message" tabindex="-1">Unsend a message <a class="header-anchor" href="#unsend-a-message" aria-label="Permalink to “Unsend a message”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Turns a message in chat into &quot;This message was unsent.&quot;</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/message/unsend</span></span></code></pre></div><p>Body:</p><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageId</code> — string, must be sent by you</li></ul><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>500</code> — Internal Error if conversation or message was not found or if it wasn&#39;t sent by you</li></ul><h2 id="delete-a-message" tabindex="-1">Delete a message <a class="header-anchor" href="#delete-a-message" aria-label="Permalink to “Delete a message”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Deletes a message on your side. Does not delete message for other chat participant.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/message/delete</span></span></code></pre></div><p>Body:</p><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageId</code> — string, must be sent by you</li></ul><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>500</code> — Internal Error if conversation or message was not found</li></ul><h2 id="send-typing-indicator-wip" tabindex="-1">Send typing indicator, WIP <a class="header-anchor" href="#send-typing-indicator-wip" aria-label="Permalink to “Send typing indicator, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>WIP, does not seem to work.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chatstatus/typing</span></span></code></pre></div><p>Body:</p><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>status</code> — string, either <code>&quot;Typing&quot;</code> or <code>&quot;Cleared&quot;</code></li></ul><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>403</code> — Action not permitted if conversation not found</li></ul><h2 id="react-to-a-message" tabindex="-1">React to a message <a class="header-anchor" href="#react-to-a-message" aria-label="Permalink to “React to a message”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>There is no discovered way to undo the reaction as of yet.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/chat/message/reaction</span></span></code></pre></div><p>Body:</p><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageId</code> — string</li><li><code>reactionType</code> — integer, (<code>1</code> is &quot;🔥&quot;)</li></ul><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>500</code> — Internal Error if conversation or message was not found</li></ul><h2 id="messagereaction" tabindex="-1">MessageReaction <a class="header-anchor" href="#messagereaction" aria-label="Permalink to “MessageReaction”">​</a></h2><ul><li><code>profileId</code> — integer</li><li><code>reactionType</code> — integer, (<code>1</code> is &quot;🔥&quot;)</li></ul><h2 id="message-type" tabindex="-1">Message type <a class="header-anchor" href="#message-type" aria-label="Permalink to “Message type”">​</a></h2><p>Message type discriminator. There also appears to be a related <code>chat1Type</code>, could be legacy type.</p><ul><li><code>&quot;Album&quot;</code></li><li><code>&quot;AlbumContentReaction&quot;</code></li><li><code>&quot;AlbumContentReply&quot;</code></li><li><code>&quot;Audio&quot;</code></li><li><code>&quot;ExpiringAlbum&quot;</code></li><li><code>&quot;ExpiringAlbumV2&quot;</code></li><li><code>&quot;ExpiringImage&quot;</code></li><li><code>&quot;Video&quot;</code></li><li><code>&quot;Gaymoji&quot;</code></li><li><code>&quot;Generative&quot;</code></li><li><code>&quot;Giphy&quot;</code></li><li><code>&quot;Image&quot;</code></li><li><code>&quot;Location&quot;</code></li><li><code>&quot;PrivateVideo&quot;</code></li><li><code>&quot;ProfileLink&quot;</code></li><li><code>&quot;ProfilePhotoReply&quot;</code></li><li><code>&quot;Retract&quot;</code></li><li><code>&quot;Text&quot;</code></li><li><code>&quot;Unknown&quot;</code></li><li><code>&quot;NonExpiringVideo&quot;</code></li><li><code>&quot;VideoCall&quot;</code></li></ul><h2 id="chat1messagetype" tabindex="-1">Chat1MessageType <a class="header-anchor" href="#chat1messagetype" aria-label="Permalink to “Chat1MessageType”">​</a></h2><p>Legacy message type.</p><ul><li><code>&quot;map&quot;</code></li><li><code>&quot;image&quot;</code></li><li><code>&quot;expiring_album&quot;</code></li><li><code>&quot;expiring_image&quot;</code></li><li><code>&quot;private_video&quot;</code></li><li><code>&quot;expiring_video&quot;</code></li><li><code>&quot;gaymoji&quot;</code></li><li><code>&quot;giphy&quot;</code></li><li><code>&quot;audio&quot;</code></li><li><code>&quot;video_call&quot;</code></li><li><code>&quot;video_call_v3&quot;</code></li><li><code>&quot;audio_call&quot;</code></li><li><code>&quot;text&quot;</code></li><li><code>&quot;unknown&quot;</code></li><li><code>&quot;retracted&quot;</code></li><li><code>&quot;retracted_location&quot;</code></li><li><code>&quot;album_share&quot;</code></li><li><code>&quot;album_react&quot;</code></li><li><code>&quot;album_content_reaction&quot;</code></li><li><code>&quot;album_content_reply&quot;</code></li></ul><h2 id="albummessagebody" tabindex="-1">AlbumMessageBody <a class="header-anchor" href="#albummessagebody" aria-label="Permalink to “AlbumMessageBody”">​</a></h2><p>Body for <code>&quot;Album&quot;</code> message type. Includes everything from AlbumPreview and AlbumExpiration.</p><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumpreview">AlbumPreview</a></em></li><li><em>everything from <a href="/grindr-api/messaging/albums#albumexpiration">AlbumExpiration</a></em></li><li><code>coverUrl</code> — string or <code>null</code></li><li><code>ownerProfileId</code> — number or <code>null</code> if album has expired or was locked</li><li><code>isViewable</code> — boolean</li><li><code>hasVideo</code> — boolean</li><li><code>hasPhoto</code> — boolean</li><li><code>viewableUntil</code> — number or <code>null</code></li></ul><h2 id="albumcontentreactionbody" tabindex="-1">AlbumContentReactionBody <a class="header-anchor" href="#albumcontentreactionbody" aria-label="Permalink to “AlbumContentReactionBody”">​</a></h2><p>Body for <code>&quot;AlbumContentReaction&quot;</code> message type. Implies &quot;🔥&quot; reaction as there does not appear to be any choice.</p><ul><li><code>albumId</code> — integer</li><li><code>ownerProfileId</code> — integer or <code>null</code> if album has expired or was locked</li><li><code>albumContentId</code> — integer</li><li><code>previewUrl</code> — string or <code>null</code> if album has expired or was locked, see <a href="/grindr-api/media/signed-cdn-files#chat-media">Signed CDN files -&gt; Chat media</a></li><li><code>expiresAt</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>viewable</code> — boolean</li></ul><h2 id="albumcontentreplybody" tabindex="-1">AlbumContentReplyBody <a class="header-anchor" href="#albumcontentreplybody" aria-label="Permalink to “AlbumContentReplyBody”">​</a></h2><p>Body for <code>&quot;AlbumContentReply&quot;</code> message type. Extends AlbumContentReaction.</p><ul><li><em>everything from <a href="/grindr-api/messaging/messages#albumcontentreactionbody">AlbumContentReactionBody</a></em></li><li><code>albumContentReply</code> — string</li><li><code>contentType</code> — string or <code>null</code> if album has expired or was locked</li></ul><h2 id="audiomessagebody" tabindex="-1">AudioMessageBody <a class="header-anchor" href="#audiomessagebody" aria-label="Permalink to “AudioMessageBody”">​</a></h2><p>Body for <code>&quot;Audio&quot;</code> message type.</p><ul><li><code>mediaId</code> — number</li><li><code>mediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a> or <code>null</code></li><li><code>url</code> — string, see <a href="/grindr-api/media/signed-cdn-files#chat-media">Signed CDN files -&gt; Chat media</a></li><li><code>contentType</code> — string, e.g. <code>audio/aac</code></li><li><code>length</code> — number in milliseconds (1/1000th of a second) or <code>null</code></li><li><code>expiresAt</code> — unix timestamp in milliseconds, 15 minutes</li></ul><h2 id="videomessagebody" tabindex="-1">VideoMessageBody <a class="header-anchor" href="#videomessagebody" aria-label="Permalink to “VideoMessageBody”">​</a></h2><p>Body for <code>&quot;Video&quot;</code> message type. Additionally, for expiring videos <code>viewsRemaining</code> is set; capped at <code>2147483647</code> for &quot;unlimited&quot; views.</p><ul><li><code>mediaId</code> — number or <code>null</code></li><li><code>url</code> — string or <code>null</code></li><li><code>fileCacheKey</code> — string</li><li><code>contentType</code> — string or <code>null</code></li><li><code>length</code> — number</li><li><code>maxViews</code> — integer or <code>null</code></li><li><code>looping</code> — boolean or <code>null</code></li><li><code>viewsRemaining</code> — integer, optional</li></ul><h2 id="privatevideobody" tabindex="-1">PrivateVideoBody <a class="header-anchor" href="#privatevideobody" aria-label="Permalink to “PrivateVideoBody”">​</a></h2><p>Body for <code>&quot;PrivateVideo&quot;</code> message type. Extends <a href="#video">Video</a>.</p><ul><li><em>everything from <a href="/grindr-api/messaging/messages#videomessagebody">VideoMessageBody</a></em></li><li><code>viewCount</code> — integer</li></ul><h2 id="gaymojibody" tabindex="-1">GaymojiBody <a class="header-anchor" href="#gaymojibody" aria-label="Permalink to “GaymojiBody”">​</a></h2><p>Body for <code>&quot;Gaymoji&quot;</code> message type.</p><ul><li><code>imageHash</code> — string</li></ul><h2 id="giphybody" tabindex="-1">GiphyBody <a class="header-anchor" href="#giphybody" aria-label="Permalink to “GiphyBody”">​</a></h2><p>Body for <code>&quot;Giphy&quot;</code> message type. URLs point at <code>https://media0.giphy.com</code>.</p><ul><li><code>id</code> — string</li><li><code>urlPath</code> — full URL to gif file</li><li><code>stillPath</code> — single frame, URL to gif file</li><li><code>previewPath</code> — string</li><li><code>width</code> — integer</li><li><code>height</code> — integer</li><li><code>imageHash</code> — string</li></ul><h2 id="imagemessagebody" tabindex="-1">ImageMessageBody <a class="header-anchor" href="#imagemessagebody" aria-label="Permalink to “ImageMessageBody”">​</a></h2><p>Body for <code>&quot;Image&quot;</code> message type. Additional fields are present only for regular (non-expiring) images.</p><ul><li><code>mediaId</code> — number</li><li><code>width</code> — integer or <code>null</code></li><li><code>height</code> — integer or <code>null</code></li><li><code>url</code> — string</li><li><code>imageHash</code> — string</li><li><code>takenOnGrindr</code> — boolean or <code>null</code></li><li><code>createdAt</code> — unix timestamp in milliseconds or <code>null</code></li></ul><h2 id="chatimagebody" tabindex="-1">ChatImageBody <a class="header-anchor" href="#chatimagebody" aria-label="Permalink to “ChatImageBody”">​</a></h2><p>&quot;ChatImage&quot; message body.</p><ul><li><code>mediaId</code> — number</li><li><code>url</code> — string</li><li><code>expiresAt</code> — unix timestamp in milliseconds</li><li><code>takenOnGrindr</code> — boolean</li><li><code>createdTs</code> — unix timestamp in milliseconds</li></ul><h2 id="expiringimagebody" tabindex="-1">ExpiringImageBody <a class="header-anchor" href="#expiringimagebody" aria-label="Permalink to “ExpiringImageBody”">​</a></h2><p>Body for <code>&quot;ExpiringImage&quot;</code> message type. Extends <a href="#image">Image</a> but with <code>url</code> set to <code>null</code> and additional <code>viewsRemaining</code>.</p><p>To get a single-use expiring image URL, you need to call <a href="/grindr-api/messaging/messages#get-a-single-message-in-a-conversation">Get a single message in a conversation</a>. After one call, <code>url</code> in message body will be replaced with <code>null</code> and image will no longer be viewable.</p><ul><li><em>everything from <a href="/grindr-api/messaging/messages#imagemessagebody">ImageMessageBody</a></em></li><li><code>url</code> — string or <code>null</code></li><li><code>viewsRemaining</code> — number or <code>null</code></li></ul><h2 id="locationmessagebody" tabindex="-1">LocationMessageBody <a class="header-anchor" href="#locationmessagebody" aria-label="Permalink to “LocationMessageBody”">​</a></h2><p>Body for <code>&quot;Location&quot;</code> message type.</p><ul><li><code>lat</code> — number</li><li><code>lon</code> — number</li></ul><h2 id="profilephotoreplybody" tabindex="-1">ProfilePhotoReplyBody <a class="header-anchor" href="#profilephotoreplybody" aria-label="Permalink to “ProfilePhotoReplyBody”">​</a></h2><p>Body for <code>&quot;ProfilePhotoReply&quot;</code> message type. Unknown, WIP.</p><ul><li><code>imageHash</code> — string</li><li><code>photoContentReply</code> — string</li></ul><h2 id="retractmessagebody" tabindex="-1">RetractMessageBody <a class="header-anchor" href="#retractmessagebody" aria-label="Permalink to “RetractMessageBody”">​</a></h2><p>Body for <code>&quot;Retract&quot;</code> message type. Unknown, WIP.</p><ul><li><code>targetMessageId</code> — string</li></ul><h2 id="textmessagebody" tabindex="-1">TextMessageBody <a class="header-anchor" href="#textmessagebody" aria-label="Permalink to “TextMessageBody”">​</a></h2><p>Body for <code>&quot;Text&quot;</code> message type.</p><ul><li><code>text</code> — string</li></ul><h2 id="videocallmessagebody" tabindex="-1">VideoCallMessageBody <a class="header-anchor" href="#videocallmessagebody" aria-label="Permalink to “VideoCallMessageBody”">​</a></h2><p>Body for <code>&quot;VideoCall&quot;</code> message type. WIP. Only for &quot;status&quot; messages.</p><ul><li><code>result</code> — string or <code>null</code>, appears to have the following values: <code>SUCCESSFUL</code>, <code>Duration:</code>, <code>Busy</code>, <code>BUSY</code>, <code>Cancelled</code>, <code>Declined</code>, <code>DECLINED</code>, <code>Missed</code>, <code>AB_Unsupported</code>, <code>No_Answer</code>, <code>UNANSWERED</code>, <code>Lite_Unsupport</code></li><li><code>videoCallDuration</code> — number or <code>null</code></li></ul><h2 id="unknownmessagebody" tabindex="-1">UnknownMessageBody <a class="header-anchor" href="#unknownmessagebody" aria-label="Permalink to “UnknownMessageBody”">​</a></h2><p>Empty type.</p><h2 id="message-contents" tabindex="-1">Message contents <a class="header-anchor" href="#message-contents" aria-label="Permalink to “Message contents”">​</a></h2><ul><li><a href="/grindr-api/messaging/messages#albummessagebody">AlbumMessageBody</a></li><li><a href="/grindr-api/messaging/messages#albumcontentreactionbody">AlbumContentReactionBody</a></li><li><a href="/grindr-api/messaging/messages#albumcontentreplybody">AlbumContentReplyBody</a></li><li><a href="/grindr-api/messaging/messages#audiomessagebody">AudioMessageBody</a></li><li><a href="/grindr-api/messaging/messages#videomessagebody">VideoMessageBody</a></li><li><a href="/grindr-api/messaging/messages#privatevideobody">PrivateVideoBody</a></li><li><a href="/grindr-api/messaging/messages#gaymojibody">GaymojiBody</a></li><li><a href="/grindr-api/messaging/messages#giphybody">GiphyBody</a></li><li><a href="/grindr-api/messaging/messages#imagemessagebody">ImageMessageBody</a></li><li><a href="/grindr-api/messaging/messages#chatimagebody">ChatImageBody</a></li><li><a href="/grindr-api/messaging/messages#expiringimagebody">ExpiringImageBody</a></li><li><a href="/grindr-api/messaging/messages#locationmessagebody">LocationMessageBody</a></li><li><a href="/grindr-api/messaging/messages#profilephotoreplybody">ProfilePhotoReplyBody</a></li><li><a href="/grindr-api/messaging/messages#retractmessagebody">RetractMessageBody</a></li><li><a href="/grindr-api/messaging/messages#textmessagebody">TextMessageBody</a></li><li><a href="/grindr-api/messaging/messages#videocallmessagebody">VideoCallMessageBody</a></li><li><a href="/grindr-api/messaging/messages#unknownmessagebody">UnknownMessageBody</a></li><li><a href="/grindr-api/messaging/messages#expiringalbumbody">ExpiringAlbumBody</a></li><li><a href="/grindr-api/messaging/messages#expiringalbumv2body">ExpiringAlbumV2Body</a></li><li><a href="/grindr-api/messaging/messages#nonexpiringvideobody">NonExpiringVideoBody</a></li><li><a href="/grindr-api/messaging/messages#generativebody">GenerativeBody</a></li><li><a href="/grindr-api/messaging/messages#profilelinkbody">ProfileLinkBody</a></li></ul><h2 id="message" tabindex="-1">Message <a class="header-anchor" href="#message" aria-label="Permalink to “Message”">​</a></h2><ul><li><code>messageId</code> — string, appears to be a unix timestamp in milliseconds and UUIDv4 separated by <code>:</code>, e.g. <code>&quot;1774296692000:843daee8-1e93-47d6-bc7f-3d981925a393&quot;</code></li><li><code>conversationId</code> — string, see <a href="/grindr-api/messaging/conversations#conversation">Conversation</a></li><li><code>senderId</code> — number</li><li><code>timestamp</code> — unix timestamp in milliseconds, appears to be same as in <code>messageId</code></li><li><code>unsent</code> — boolean, if this is true, <code>body</code> is set to <code>null</code></li><li><code>reactions</code> — array of <a href="/grindr-api/messaging/messages#messagereaction">MessageReaction</a></li><li><code>type</code> — string, see <a href="/grindr-api/messaging/messages#message-type">Message type</a></li><li><code>body</code> — object with <a href="/grindr-api/messaging/messages#message-contents">Message contents</a> or <code>null</code></li><li><code>replyToMessage</code> — unknown or <code>null</code></li><li><code>dynamic</code> — boolean, unknown purpose, WIP</li><li><code>chat1Type</code> — string, see <a href="/grindr-api/messaging/messages#message-type">Message type</a></li><li><code>replyPreview</code> — unknown or <code>null</code></li></ul><h2 id="conversationmessagesresponse" tabindex="-1">ConversationMessagesResponse <a class="header-anchor" href="#conversationmessagesresponse" aria-label="Permalink to “ConversationMessagesResponse”">​</a></h2><ul><li><code>lastReadTimestamp</code> — unix timestamp of recipient&#39;s side in milliseconds or <code>null</code>; is not affected by yours calls to <a href="/grindr-api/messaging/conversations#mark-messages-as-read">mark messages as read</a></li><li><code>messages</code> — array of <a href="/grindr-api/messaging/messages#message">Message</a></li><li><code>metadata</code> — object <ul><li><code>translate</code> — boolean</li><li><code>hasSharedAlbums</code> — boolean</li><li><code>isInAList</code> — boolean</li></ul></li><li><code>profile</code> — object if <code>profile</code> query parameter is set to <code>true</code> or <code>null</code></li></ul><h2 id="messagetarget" tabindex="-1">MessageTarget <a class="header-anchor" href="#messagetarget" aria-label="Permalink to “MessageTarget”">​</a></h2><ul><li><code>type</code> — string, <code>Direct</code>, <code>Group</code>, <code>HumanWingman</code></li><li><code>targetId</code> — integer</li></ul><h2 id="sendmessagerequest" tabindex="-1">SendMessageRequest <a class="header-anchor" href="#sendmessagerequest" aria-label="Permalink to “SendMessageRequest”">​</a></h2><ul><li><code>type</code> — <a href="/grindr-api/messaging/messages#message-type">Message type</a></li><li><code>target</code> — <a href="/grindr-api/messaging/messages#messagetarget">MessageTarget</a></li><li><code>body</code> — object with <a href="/grindr-api/messaging/messages#message-contents">Message contents</a> or <code>null</code></li></ul><p>Additional body fields for websocket only:</p><ul><li><code>replyToMessageId</code> — string or <code>null</code></li></ul><h2 id="messagemutationrequest" tabindex="-1">MessageMutationRequest <a class="header-anchor" href="#messagemutationrequest" aria-label="Permalink to “MessageMutationRequest”">​</a></h2><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageId</code> — string, must be sent by you</li></ul><h2 id="typingindicatorrequest" tabindex="-1">TypingIndicatorRequest <a class="header-anchor" href="#typingindicatorrequest" aria-label="Permalink to “TypingIndicatorRequest”">​</a></h2><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>status</code> — string, either <code>&quot;Typing&quot;</code> or <code>&quot;Cleared&quot;</code></li></ul><h2 id="messagereactionrequest" tabindex="-1">MessageReactionRequest <a class="header-anchor" href="#messagereactionrequest" aria-label="Permalink to “MessageReactionRequest”">​</a></h2><ul><li><code>conversationId</code> — <a href="/grindr-api/messaging/conversations#conversation-id">Conversation ID</a></li><li><code>messageId</code> — string</li><li><code>reactionType</code> — integer, (<code>1</code> is &quot;🔥&quot;)</li></ul><h2 id="expiringalbumbody" tabindex="-1">ExpiringAlbumBody <a class="header-anchor" href="#expiringalbumbody" aria-label="Permalink to “ExpiringAlbumBody”">​</a></h2><p>Body for <code>&quot;ExpiringAlbum&quot;</code> message type. Extends <a href="#album-message-body">Album</a>.</p><ul><li><em>everything from <a href="/grindr-api/messaging/messages#albummessagebody">AlbumMessageBody</a></em></li></ul><h2 id="expiringalbumv2body" tabindex="-1">ExpiringAlbumV2Body <a class="header-anchor" href="#expiringalbumv2body" aria-label="Permalink to “ExpiringAlbumV2Body”">​</a></h2><p>Body for <code>&quot;ExpiringAlbumV2&quot;</code> message type. For <a href="/grindr-api/messaging/albums#albumexpirationtype">AlbumExpirationType</a> = <code>ONCE</code> but might have other values if expiration settings were changed later. Extends <a href="#expiring-album-body">ExpiringAlbum</a>.</p><ul><li><em>everything from <a href="/grindr-api/messaging/messages#expiringalbumbody">ExpiringAlbumBody</a></em></li></ul><h2 id="nonexpiringvideobody" tabindex="-1">NonExpiringVideoBody <a class="header-anchor" href="#nonexpiringvideobody" aria-label="Permalink to “NonExpiringVideoBody”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This type hasn&#39;t been researched yet</p></div><p>Body for <code>&quot;NonExpiringVideo&quot;</code> message type. Unknown, WIP.</p><h2 id="generativebody" tabindex="-1">GenerativeBody <a class="header-anchor" href="#generativebody" aria-label="Permalink to “GenerativeBody”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This type hasn&#39;t been researched yet</p></div><p>Body for <code>&quot;Generative&quot;</code> message type. Unknown, WIP.</p><h2 id="profilelinkbody" tabindex="-1">ProfileLinkBody <a class="header-anchor" href="#profilelinkbody" aria-label="Permalink to “ProfileLinkBody”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This type hasn&#39;t been researched yet</p></div><p>Body for <code>&quot;ProfileLink&quot;</code> message type. Unknown, WIP.</p>',160)])])}const u=a(d,[["render",l]]);export{m as __pageData,u as default};
